  std::swap(DRAG_AREA, o.DRAG_AREA);
  std::swap(DRAG_COEFF, o.DRAG_COEFF);
  std::swap(COMMENT, o.COMMENT);
  std::swap(CLASSIFICATION, o.CLASSIFICATION);
  std::swap(MESSAGE_ID, o.MESSAGE_ID);
